var t={rx:.44,rz:.37,h:.42,scale:.9,yOff:-.12,cam:4};function u(a,c){return Math.cbrt(Math.abs(a/t.rx)**3+Math.abs(c/t.rz)**3)}function P(a,c){let s=u(a,c),n=t.h;return s<1?n*(1-.3*s**4):n*.7*Math.exp(-(s-1)*3.1)}function m(a,c,s,n,o,x){let h=n*Math.PI/180,r=o*Math.PI/180,e=a,f=s*Math.sin(h)+c*Math.cos(h),M=c*Math.sin(h)-s*Math.cos(h),b=(e*Math.cos(r)+M*Math.sin(r))*t.scale,i=f*t.scale+t.yOff,l=(-e*Math.sin(r)+M*Math.cos(r))*t.scale,p=t.cam/(t.cam-l);return b*=p,i*=p*x,[b,i,l]}function v(a){let c=a*Math.PI/180,s=Math.cos(c),n=Math.sin(c),o=1/Math.cbrt(Math.abs(s/t.rx)**3+Math.abs(n/t.rz)**3);return[s*o,n*o]}export{t as a,P as b,m as c,v as d};
